import type { ConfigPlugin } from '@expo/config-plugins';
import { withProjectBuildGradle } from '@expo/config-plugins';

import * as semver from 'semver';

import {
  CIO_GOOGLE_SERVICES_MIN_VERSION,
  CIO_PROJECT_BUILDSCRIPTS_REGEX,
  CIO_PROJECT_GOOGLE_SNIPPET,
  CIO_PROJECT_GOOGLE_SNIPPET_ANY_VERSION_REGEX,
} from './../helpers/constants/android';
import type { CustomerIOPluginOptionsAndroid } from './../types/cio-types';

export function modifyProjectBuildGradleForGoogleServices(contents: string): string {
  // An incremental prebuild of a project generated by an earlier plugin version already has the
  // line, possibly at an older version. Raise it in place rather than adding a second one, keeping
  // its indentation and line ending, and never lower a version someone already raised.
  const injected = contents.match(CIO_PROJECT_GOOGLE_SNIPPET_ANY_VERSION_REGEX);
  if (injected) {
    const version = semver.coerce(injected[2]);
    if (version && semver.gte(version, CIO_GOOGLE_SERVICES_MIN_VERSION)) {
      return contents;
    }
    return contents.replace(
      CIO_PROJECT_GOOGLE_SNIPPET_ANY_VERSION_REGEX,
      `$1${CIO_GOOGLE_SERVICES_MIN_VERSION}$3`
    );
  }
  return contents.replace(
    CIO_PROJECT_BUILDSCRIPTS_REGEX,
    `$1\n${CIO_PROJECT_GOOGLE_SNIPPET}`
  );
}

export const withProjectGoogleServices: ConfigPlugin<
  CustomerIOPluginOptionsAndroid
> = (configOuter) => {
  return withProjectBuildGradle(configOuter, (props) => {
    props.modResults.contents = modifyProjectBuildGradleForGoogleServices(
      props.modResults.contents
    );
    return props;
  });
};
